// v3 - API tabanlı, hata gosterimli
console.log("[Kimlik] Script yuklendi v3");

var form = document.querySelector("#form");

if (!form) {
  console.error("[Kimlik] Form bulunamadi!");
} else {
  form.addEventListener("submit", async function (e) {
    e.preventDefault();
    console.log("[Kimlik] Form submit tetiklendi");

    var submitBtn = form.querySelector('[type="submit"]');
    var originalText = submitBtn.innerHTML;

    submitBtn.innerHTML = "Lutfen bekleyin...";
    submitBtn.disabled = true;

    try {
      var formData = new FormData(form);

      // Fotograf secildi mi?
      var imageFile = form.querySelector('[name="image"]').files[0];
      if (!imageFile) {
        alert("Lutfen bir fotograf secin!");
        return;
      }

      console.log("[Kimlik] API'ya istek atiliyor...");

      var res = await fetch("/api/generate", {
        method: "POST",
        body: formData,
      });

      console.log("[Kimlik] API yaniti:", res.status);

      var data = await res.json();
      console.log("[Kimlik] API data:", data.success);

      if (!data.success) {
        alert("Hata: " + (data.error || "Bilinmeyen hata"));
        return;
      }

      // Gorselleri yerlestir
      document.querySelector(".front-image").src = data.front;
      document.querySelector(".back-image").src = data.back;

      // Basari mesaji
      document.querySelector(".text-one").classList.add("d-none");
      document.querySelector(".text-two").classList.remove("d-none");

      // Indirme butonlari
      document.querySelector("#download-front").disabled = false;
      document.querySelector("#download-back").disabled = false;

    } catch (err) {
      console.error("[Kimlik] Hata:", err);
      alert("Hata olustu: " + err.message);
    } finally {
      submitBtn.innerHTML = originalText;
      submitBtn.disabled = false;
    }
  });
}

// On yuz indir
document.querySelector("#download-front").addEventListener("click", function () {
  var a = document.createElement("a");
  a.href = document.querySelector(".front-image").src;
  a.download = "on-yuz.png";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
});

// Arka yuz indir
document.querySelector("#download-back").addEventListener("click", function () {
  var a = document.createElement("a");
  a.href = document.querySelector(".back-image").src;
  a.download = "arka-yuz.png";
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
});
